<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';
$user=require_login($pdo); $pageTitle=t('dashboard.title');
header('Cache-Control: private, no-store');
$listingNotice=null;
if (($_SERVER['REQUEST_METHOD']??'')==='GET') {
    $listingNotice=match ($_SESSION['listing_dashboard_notice']??null) {
        'saved'=>'dashboard.saved',
        'changed'=>'listing_validation.changed',
        default=>null,
    };
    unset($_SESSION['listing_dashboard_notice']);
}
$q=$pdo->prepare("SELECT editor_id,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.title')) AS title FROM market_listing_drafts WHERE seller_id=? AND payload IS NOT NULL ORDER BY updated_at DESC,editor_id LIMIT 12");
$q->execute([(int)$user['id']]);$draftWorkspaces=$q->fetchAll();
$pageRaw=$_GET['page'] ?? '1'; $page=is_string($pageRaw)&&ctype_digit($pageRaw)?max(1,min(10000,(int)$pageRaw)):1;
$q=$pdo->prepare('SELECT COUNT(*) FROM market_listings WHERE seller_id=?'); $q->execute([$user['id']]); $total=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT status,COUNT(*) AS count FROM market_listings WHERE seller_id=? GROUP BY status'); $q->execute([$user['id']]); $stats=array_column($q->fetchAll(),'count','status');
$q=$pdo->prepare('SELECT l.*,c.name AS category_name,EXISTS(SELECT 1 FROM market_proxy_bids p WHERE p.listing_id=l.id) AS has_bids,EXISTS(SELECT 1 FROM market_bids b WHERE b.listing_id=l.id AND b.event_type=\'close_no_bid\') AS closed_unsold,EXISTS(SELECT 1 FROM market_bids b WHERE b.listing_id=l.id AND b.user_id=l.highest_bidder_id AND b.amount_cents=l.current_bid_cents AND ((l.status=\'sold\' AND b.idempotency_key=CONCAT(\'buyout-\',l.id) AND b.event_type=\'buyout\') OR (l.status=\'ended\' AND b.idempotency_key=CONCAT(\'close-\',l.id) AND b.event_type=\'close\'))) AS closed_sold FROM market_listings l JOIN market_categories c ON c.id=l.category_id WHERE l.seller_id=? ORDER BY l.created_at DESC,l.id DESC LIMIT 20 OFFSET '.(($page-1)*20)); $q->execute([$user['id']]); $listings=$q->fetchAll();
$labels=['draft'=>t('dashboard.status_draft'),'active'=>t('Aktiv'),'paused'=>t('dashboard.status_paused'),'ended'=>t('dashboard.status_ended'),'sold'=>t('dashboard.status_sold'),'archived'=>t('dashboard.status_archived'),'review'=>t('dashboard.status_review')];
include __DIR__.'/../includes/header.php';
?>
<main class="page dashboard-page"><div class="page-heading"><p class="eyebrow"><?=h(t('dashboard.eyebrow'))?></p><h1><?=h(t('dashboard.greeting',['username'=>$user['username']]))?></h1><p class="muted"><?=h(t('dashboard.summary'))?></p><div class="button-row"><a class="button" href="/user/create-listing.php"><?=h(t('Inserat erstellen'))?></a><a class="button button-ghost" href="/user/profile.php"><?=h(t('dashboard.profile'))?></a><?php if ($canOpenAdmin): ?><a class="button secondary" href="/admin/index.php"><?=ui_icon('shield')?><?=h(t('refine.open_admin'))?></a><?php endif; ?></div></div>
<?php if ($listingNotice!==null): ?><p class="notice" role="status"><?=h(t($listingNotice))?></p><?php endif; ?>
<p><a class="button secondary" href="/user/sessions.php"><?=h(t('sessions.title'))?></a> <a class="button secondary" href="/user/trades.php"><?=h(t('trade.title'))?></a> <a class="button secondary" href="/user/personal.php"><?=h(t('personal.title'))?></a></p>
<?php if($draftWorkspaces):?><section class="panel"><h2><?=h(t('draft.workspaces'))?></h2><ul><?php foreach($draftWorkspaces as $workspace):?><li><a href="/user/listing-draft.php?editor=<?=(int)$workspace['editor_id']?>"><?=h($workspace['title']?:t('draft.untitled'))?></a></li><?php endforeach;?></ul></section><?php endif;?>
<div class="stat-grid"><div class="stat-card"><span><?=h(t('Alle Angebote'))?></span><strong><?= $total ?></strong></div><div class="stat-card"><span><?=h(t('Aktiv'))?></span><strong><?= (int)($stats['active'] ?? 0) ?></strong></div><div class="stat-card"><span><?=h(t('dashboard.drafts'))?></span><strong><?= (int)($stats['draft'] ?? 0) ?></strong></div><div class="stat-card"><span><?=h(t('dashboard.sold_ended'))?></span><strong><?= (int)($stats['sold'] ?? 0)+(int)($stats['ended'] ?? 0) ?></strong></div></div>
<section class="panel"><nav class="button-row" aria-label="<?=h(t('dashboard.areas'))?>"><a class="button secondary" href="/user/messages.php"><?=h(t('Nachrichten'))?></a><a class="button secondary" href="/user/watchlist.php"><?=h(t('dashboard.watchlist'))?></a><a class="button secondary" href="/user/payments.php"><?=h(t('dashboard.payments'))?></a></nav><a class="button secondary" href="/user/notifications.php"><?=h(t('Benachrichtigungen'))?></a><a class="button secondary" href="/user/wanted.php"><?=h(t('Meine Gesuche'))?></a><a class="button secondary" href="/user/saved-searches.php"><?=h(t('dashboard.alerts'))?></a><a class="button secondary" href="/user/promotions.php"><?=h(t('dashboard.promotions'))?></a><a class="button secondary" href="/user/dealer.php"><?=h(t('dashboard.dealer'))?></a><a class="button secondary" href="/user/invoices.php"><?=h(t('dashboard.invoices'))?></a><a class="button secondary" href="/user/privacy.php"><?=h(t('dashboard.privacy'))?></a><a class="button secondary" href="/user/verification.php"><?=h(t('dashboard.verification'))?></a><a class="button secondary" href="/user/reports.php"><?=h(t('dashboard.reports'))?></a><h2><?=h(t('dashboard.listings'))?></h2><p><a class="button secondary" href="/user/billing.php"><?=h(t('dashboard.billing'))?></a></p><?php if (!$listings): ?><p><?=h(t('dashboard.empty'))?></p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th><?=h(t('personal.listing'))?></th><th><?=h(t('dashboard.status'))?></th><th><?=h(t('personal.price'))?></th><th><?=h(t('dashboard.actions'))?></th></tr></thead><tbody><?php foreach ($listings as $listing): $editable=in_array($listing['status'],['draft','active','paused'],true)&&!$listing['has_bids']&&!($listing['type']==='auction'&&$listing['status']==='active'&&market_expired($listing)); ?><tr><td><strong><?= h($listing['title']) ?></strong><br><small><?= h(i18n_category($pdo,$listing)) ?></small></td><td><span class="status"><?= h($labels[$listing['status']] ?? $listing['status']) ?></span></td><td><?= h(money_eur((int)($listing['current_bid_cents'] ?? $listing['price_cents']))) ?></td><td><div class="button-row"><?php if (in_array($listing['status'],['active','ended','sold'],true) && catalog_category_allowed($pdo,(int)$listing['category_id'])): ?><a class="button button-ghost button-small" href="/marketplace/<?= $listing['type']==='auction'?'view-auction.php':'view-item.php' ?>?id=<?= (int)$listing['id'] ?>"><?=h(t('account.notification_view'))?></a><?php endif; ?><?php if ($listing['type']==='auction' && (($listing['status']==='ended' && !$listing['has_bids'] && $listing['closed_unsold'] && $listing['highest_bidder_id']===null && $listing['current_bid_cents']===null) || ($listing['closed_sold'] && trade_listing_available($pdo,(int)$listing['id'])))): ?><a class="button button-ghost button-small" href="/user/relist.php?id=<?= (int)$listing['id'] ?>"><?=h(t('relisting.action'))?></a><?php endif; ?><?php if($listing['type']!=='auction'&&in_array($listing['status'],['archived','ended','sold'],true)&&trade_listing_available($pdo,(int)$listing['id'])):?><a class="button button-ghost button-small" href="/user/relist.php?id=<?=(int)$listing['id']?>"><?=h(t('relisting.action'))?></a><?php endif;?><?php if(relisting_extension_eligible($listing,(bool)$listing['has_bids'])):?><a class="button button-ghost button-small" href="/user/extend-listing.php?id=<?=(int)$listing['id']?>"><?=h(t('relisting.extension_action'))?></a><?php endif;?><?php if ($editable): ?><a class="button button-ghost button-small" href="/user/edit-listing.php?id=<?= (int)$listing['id'] ?>"><?=h(t('dashboard.edit'))?></a><form method="post" action="/actions/manage-auction.php"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$listing['id'] ?>"><select name="action" aria-label="<?=h(t('dashboard.listing_action'))?>"><?php if ($listing['status']==='active'): ?><option value="pause"><?=h(t('dashboard.pause'))?></option><?php endif; ?><?php if ($listing['type']!=='auction' && $listing['status']!=='active'): ?><option value="publish"><?=h(t('Veröffentlichen'))?></option><?php endif; ?><?php if ($listing['type']!=='auction'): ?><option value="sold"><?=h(t('dashboard.mark_sold'))?></option><?php endif; ?><option value="archive"><?=h(t('dashboard.archive'))?></option></select><button class="button button-ghost button-small" type="submit"><?=h(t('dashboard.execute'))?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if ($total>20): ?><nav class="pagination" aria-label="<?=h(t('dashboard.pages'))?>"><?php if ($page>1): ?><a href="?page=<?= $page-1 ?>"><?=h(t('Zurück'))?></a><?php endif; ?><span><?=h(t('dashboard.page',['page'=>$page]))?></span><?php if ($page*20<$total): ?><a href="?page=<?= $page+1 ?>"><?=h(t('Weiter'))?></a><?php endif; ?></nav><?php endif; ?>
</main>
<?php include __DIR__.'/../includes/footer.php'; ?>
